type Ticket = { category: 'hardware' | 'software' | 'other'; confidence: number };

function acceptTicket(value: unknown): Ticket {
  if (typeof value !== 'object' || value === null) throw new Error('invalid ticket');
  const ticket = value as Record<string, unknown>;
  if (!['hardware', 'software', 'other'].includes(ticket.category as string)) {
    throw new Error('invalid category');
  }
  if (typeof ticket.confidence !== 'number' || ticket.confidence < 0 || ticket.confidence > 1) {
    throw new Error('invalid confidence');
  }
  return { category: ticket.category as Ticket['category'], confidence: ticket.confidence };
}
